const items = [];
const seenLinks = new Set();

for (const input of $input.all()) {
  const xml = input.json.data || input.json.body || '';
  if (!xml) continue;

  // Extract all <item> blocks
  const itemMatches = xml.matchAll(/<item[^>]*>([\s\S]*?)<\/item>/gi);
  for (const m of itemMatches) {
    const block = m[1];

    const tag = (name) => {
      const r = block.match(new RegExp(`<${name}[^>]*>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\\/${name}>`, 'i'));
      return r ? r[1].trim() : '';
    };

    const link    = tag('link') || tag('guid');
    const title   = tag('title').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#039;/g,"'").replace(/&quot;/g,'"');
    const desc    = tag('description').replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').trim().slice(0,400);
    const pubDate = tag('pubDate');

    // Try to get image from media:content, enclosure, or og tag in description
    let imageUrl = '';
    const mediaMatch = block.match(/media:content[^>]+url="([^"]+)"/i)
                    || block.match(/enclosure[^>]+url="([^"]+)"/i);
    if (mediaMatch) imageUrl = mediaMatch[1];

    if (!link || seenLinks.has(link)) continue;
    seenLinks.add(link);

    items.push({ title, link, desc, pubDate, imageUrl });
  }
}

// Sort by most recent (if pubDate available), take top 5
items.sort((a,b) => {
  const da = a.pubDate ? new Date(a.pubDate) : new Date(0);
  const db = b.pubDate ? new Date(b.pubDate) : new Date(0);
  return db - da;
});

return items.slice(0, 5).map(a => ({ json: a }));

const item = $input.first().json;
const origTitle  = $('One At A Time').first().json.title  || '';
const origDesc   = $('One At A Time').first().json.desc   || '';
const imageUrl   = $('One At A Time').first().json.imageUrl || '';

// Extract AI response text
let aiText = '';
try {
  aiText = item.choices[0].message.content || '';
} catch(e) {
  aiText = '';
}

let parsed = null;

// Try to extract JSON from AI response (handle markdown code blocks too)
const jsonMatch = aiText.match(/```(?:json)?\s*([\s\S]*?)```/) || aiText.match(/(\{[\s\S]*\})/);
if (jsonMatch) {
  try { parsed = JSON.parse(jsonMatch[1].trim()); } catch(e) {}
}
if (!parsed) {
  try { parsed = JSON.parse(aiText.trim()); } catch(e) {}
}

// Fallback: build a safe default from the original article
if (!parsed || !parsed.headline) {
  const title = origTitle.toUpperCase().slice(0, 80);
  const isCVE     = /cve|vuln|exploit|zero.?day|breach|hack/i.test(origTitle);
  const isPatch   = /patch|update|fix|release|new version/i.test(origTitle);
  parsed = {
    template:    isCVE ? 1 : (isPatch ? 2 : 3),
    headline:    title,
    badge:       isCVE ? 'SECURITY ALERT' : (isPatch ? 'SECURITY UPDATE' : 'SECURITY GUIDE'),
    pills:       [],
    body:        origDesc.slice(0, 200),
    description: origDesc.slice(0, 300),
    caption:     `${origDesc.slice(0, 250)}\n\n#CyberRangeLabs #CyberSecurity #InfoSec #Hacking`
  };
}

// Ensure template is valid integer
parsed.template = parseInt(parsed.template) || 1;
if (![1,2,3].includes(parsed.template)) parsed.template = 1;

// Add image URL from RSS
parsed.image_url   = imageUrl;
parsed.output_path = '/root/Desktop/crl_output.png';
parsed.original_link = $('One At A Time').first().json.link || '';
parsed.caption     = parsed.caption || `${origDesc.slice(0,200)}\n\n#CyberRangeLabs #CyberSecurity`;

return [{ json: parsed }];

const data = $input.first().json;
// Build safe JSON string (escape single quotes for shell)
const jsonStr = JSON.stringify(data).replace(/'/g, "'\\''");
return [{ json: { command: `python3 /root/Desktop/crl_poster.py '${jsonStr}'`, postData: data } }];

const fs   = require('fs');
const path = require('path');

// Get output path from exec stdout or default
const stdout = ($input.first().json.stdout || '').trim();
const imgPath = stdout && stdout.endsWith('.png') ? stdout : '/root/Desktop/crl_output.png';

if (!fs.existsSync(imgPath)) {
  throw new Error(`Image file not found: ${imgPath}. Check Python script output.`);
}

const buf      = fs.readFileSync(imgPath);
const b64      = buf.toString('base64');
const caption  = $('Parse AI Response').first().json.caption || '#CyberRangeLabs';
const origLink = $('Parse AI Response').first().json.original_link || '';

return [{
  json: { caption, original_link: origLink, image_path: imgPath },
  binary: {
    photo: {
      data:     b64,
      mimeType: 'image/png',
      fileName: 'crl_post.png'
    }
  }
}];
